package com.nextrade.service; import java.time.*; import java.util.*; public final class OutboxDispatcher {public record Entry(UUID id,String type,String payload,Instant createdAt,int attempts){}private final List<Entry> pending=new ArrayList<>();public synchronized void enqueue(Entry e){pending.add(e);}public synchronized Optional<Entry> claim(){if(pending.isEmpty())return Optional.empty();Entry e=pending.removeFirst();return Optional.of(e);}public synchronized int size(){return pending.size();}}
